using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;

namespace MLInferenceServer
{
    public class ModelConnection
    {
        public string ConnectionId { get; set; }
        public string TenantId { get; set; }
        public DateTime LastUsed { get; set; }
        public bool IsActive { get; set; }
        public Dictionary<string, object> SessionState { get; set; }

        public ModelConnection(string tenantId)
        {
            ConnectionId = Guid.NewGuid().ToString();
            TenantId = tenantId;
            LastUsed = DateTime.UtcNow;
            IsActive = false;
            SessionState = new Dictionary<string, object>();
        }

        public void Reset()
        {
            LastUsed = DateTime.UtcNow;
            IsActive = true;
        }
    }

    public class ConnectionPool
    {
        private readonly ConcurrentQueue<ModelConnection> _available;
        private readonly ConcurrentDictionary<string, ModelConnection> _active;
        private readonly SemaphoreSlim _semaphore;
        private readonly int _maxSize;

        public ConnectionPool(int maxSize = 10)
        {
            _maxSize = maxSize;
            _available = new ConcurrentQueue<ModelConnection>();
            _active = new ConcurrentDictionary<string, ModelConnection>();
            _semaphore = new SemaphoreSlim(maxSize, maxSize);
        }

        public async Task<ModelConnection> AcquireAsync(string tenantId, CancellationToken ct)
        {
            await _semaphore.WaitAsync(ct);

            if (_available.TryDequeue(out var connection))
            {
                connection.Reset();
                _active[connection.ConnectionId] = connection;
                return connection;
            }

            var newConn = new ModelConnection(tenantId);
            newConn.IsActive = true;
            _active[newConn.ConnectionId] = newConn;
            return newConn;
        }

        public void Release(ModelConnection connection)
        {
            connection.IsActive = false;
            _active.TryRemove(connection.ConnectionId, out _);
            _available.Enqueue(connection);
            _semaphore.Release();
        }
    }

    public class InferenceResult
    {
        public string RequestId { get; set; }
        public string TenantId { get; set; }
        public double[] Predictions { get; set; }
        public double Confidence { get; set; }
        public string ModelVersion { get; set; }
    }

    public class InferenceRequest
    {
        public string ModelName { get; set; }
        public double[] Features { get; set; }
        public Dictionary<string, string> Parameters { get; set; }
    }

    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class InferenceController : ControllerBase
    {
        private readonly ConnectionPool _pool;
        private readonly IModelRegistry _registry;
        private static readonly ConcurrentDictionary<string, InferenceResult> _resultCache
            = new ConcurrentDictionary<string, InferenceResult>();

        public InferenceController(ConnectionPool pool, IModelRegistry registry)
        {
            _pool = pool;
            _registry = registry;
        }

        private string GetTenantId() => User.FindFirst("tenant_id")?.Value;

        private string BuildCacheKey(string modelName, double[] features)
        {
            var featureHash = features != null
                ? string.Join(",", features).GetHashCode().ToString("x8")
                : "empty";
            return $"{modelName}:{featureHash}";
        }

        [HttpPost("predict")]
        public async Task<IActionResult> Predict([FromBody] InferenceRequest request, CancellationToken ct)
        {
            var tenantId = GetTenantId();
            if (string.IsNullOrEmpty(tenantId))
                return Unauthorized();

            if (!_registry.HasAccess(tenantId, request.ModelName))
                return Forbid();

            var cacheKey = BuildCacheKey(request.ModelName, request.Features);

            if (_resultCache.TryGetValue(cacheKey, out var cached))
            {
                return Ok(cached);
            }

            ModelConnection connection = null;
            try
            {
                connection = await _pool.AcquireAsync(tenantId, ct);

                connection.SessionState["current_tenant"] = tenantId;
                connection.SessionState["model"] = request.ModelName;
                connection.SessionState["request_time"] = DateTime.UtcNow;

                var result = await ExecuteInference(connection, request, tenantId);

                _resultCache[cacheKey] = result;

                return Ok(result);
            }
            finally
            {
                if (connection != null)
                    _pool.Release(connection);
            }
        }

        [HttpGet("result/{requestId}")]
        public IActionResult GetResult(string requestId)
        {
            var tenantId = GetTenantId();
            if (string.IsNullOrEmpty(tenantId))
                return Unauthorized();

            if (_resultCache.TryGetValue(requestId, out var result))
            {
                return Ok(result);
            }

            return NotFound();
        }

        private async Task<InferenceResult> ExecuteInference(
            ModelConnection connection, InferenceRequest request, string tenantId)
        {
            await Task.Delay(50); // simulate model inference latency

            var predictions = new double[request.Features.Length];
            var rng = new Random(request.Features.GetHashCode());
            for (int i = 0; i < predictions.Length; i++)
                predictions[i] = rng.NextDouble();

            return new InferenceResult
            {
                RequestId = connection.ConnectionId,
                TenantId = tenantId,
                Predictions = predictions,
                Confidence = 0.85 + rng.NextDouble() * 0.15,
                ModelVersion = _registry.GetModelVersion(request.ModelName)
            };
        }
    }

    public interface IModelRegistry
    {
        bool HasAccess(string tenantId, string modelName);
        string GetModelVersion(string modelName);
    }
}
